import{_ as t}from"./chunks/team-access.Nfq-hDXJ.js";import{_ as a,o as n,c as s,a3 as i}from"./chunks/framework.CchDE9cb.js";const o="/capacitylens/assets/invite-created.BbuocT6r.jpg",r="/capacitylens/assets/invite-accept.B4NrOGnH.jpg",v=JSON.parse('{"title":"Invite your team","description":"Create a single-use invite link, send it however your team already talks, and get someone else signed in.","frontmatter":{"title":"Invite your team","description":"Create a single-use invite link, send it however your team already talks, and get someone else signed in."},"headers":[],"relativePath":"getting-started/invite-your-team.md","filePath":"getting-started/invite-your-team.md","lastUpdated":null}'),l={name:"getting-started/invite-your-team.md"};function c(h,e,p,d,m,u){return n(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="invite-your-team" tabindex="-1">Invite your team <a class="header-anchor" href="#invite-your-team" aria-label="Permalink to &quot;Invite your team&quot;">​</a></h1><p>This page covers getting someone else into CapacityLens: creating an invite, what they see, and how they accept it. It takes about ten seconds on your side and roughly thirty seconds on theirs. It&#39;s optional — a solo <a href="/capacitylens/reference/glossary">Owner</a> can finish setting up the schedule without inviting anyone, and can come back to this page later.</p><p>CapacityLens sends no invitation emails. You create a single-use link and paste it wherever your team already talks — Slack, a text message, whatever&#39;s fastest.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Inviting someone doesn&#39;t put them on the schedule, and adding someone to the schedule doesn&#39;t give them a sign-in. These are separate records — see <a href="/capacitylens/getting-started/roles-and-permissions">Roles and permissions</a> for why.</p></div><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>You need the Owner or <a href="/capacitylens/reference/glossary">Admin</a> role to invite people. A Viewer or Editor can still open <strong>Team &amp; access</strong> and see their own role and what it allows — they just see a note there that an Owner or Admin handles invitations, instead of the &quot;Invite someone&quot; panel. See <a href="/capacitylens/getting-started/roles-and-permissions">Roles and permissions</a>.</li></ul><h2 id="create-an-invite" tabindex="-1">Create an invite <a class="header-anchor" href="#create-an-invite" aria-label="Permalink to &quot;Create an invite&quot;">​</a></h2><ol><li><p>Open <strong>Team &amp; access</strong>. Your own access is explained at the top of the page.</p><p><img src="'+t+'" alt="Team &amp; access page showing your access summary, app members and scheduled resources cards"></p></li><li><p>Choose a role in the &quot;Invite someone&quot; panel. The consequences of that role are spelled out in plain language underneath it, and you can optionally pre-authorise a specific email address.</p></li><li><p>Copy the one-time link. It&#39;s shown exactly once — the server keeps only a hash of it — so copy it now and send it to the <a href="/capacitylens/reference/glossary">person</a>.</p><p><img src="'+o+'" alt="Invite created: single-use link shown with a Copy button"></p></li></ol><h2 id="what-the-invitee-sees" tabindex="-1">What the invitee sees <a class="header-anchor" href="#what-the-invitee-sees" aria-label="Permalink to &quot;What the invitee sees&quot;">​</a></h2><p>The invite link opens outside the normal sign-in wall, so the recipient can safely preview what they&#39;re joining before anything happens: your company name, the proposed role, what that role can and can&#39;t do, and when the link expires. Just opening the link never changes <a href="/capacitylens/reference/glossary">membership</a>.</p><p><img src="'+r+'" alt="Accept invite screen showing company, proposed Editor role, expiry and accept buttons"></p><p>From there:</p><ul><li>Someone who already has a CapacityLens sign-in signs in and explicitly accepts the invite.</li><li>Someone new creates a password sign-in and accepts in the same step.</li></ul><p>Either way, they land directly on your schedule with their role visible.</p><h2 id="pending-invites" tabindex="-1">Pending invites <a class="header-anchor" href="#pending-invites" aria-label="Permalink to &quot;Pending invites&quot;">​</a></h2><p>Invites that haven&#39;t been accepted yet stay listed on <strong>Team &amp; access</strong> as pending, along with your current members. Owners and Admins can see this list; other roles only see their own access.</p><h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><p><strong>I lost the link before sending it — can I get it back?</strong> No. CapacityLens shows a one-time link&#39;s token exactly once and stores only a hash of it afterwards, so nobody — including you — can retrieve the original link again. Revoke the invite on <strong>Team &amp; access</strong> and create a new one instead; the old link stops working as soon as you revoke it.</p><p><strong>Can I run more than one company on this install?</strong> Not by default — a fresh install allows exactly one company. An administrator can turn on <code>CAPACITYLENS_MULTI_ACCOUNT</code> to allow more; see <a href="/capacitylens/self-hosting/configuration">Configuration</a>.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p><a href="/capacitylens/getting-started/roles-and-permissions">Roles and permissions</a> explains exactly what each role can see and do, so you can pick the right one next time.</p>',21)])])}const f=a(l,[["render",c]]);export{v as __pageData,f as default};
